create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, avatar_url text, created_at timestamptz not null default now());
create table public.folders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, description text, color text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.meetings (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, google_event_id text, title text not null, starts_at timestamptz, ends_at timestamptz, location text, created_at timestamptz not null default now(), unique(user_id, google_event_id));
create table public.meeting_attendees (id uuid primary key default gen_random_uuid(), meeting_id uuid not null references public.meetings(id) on delete cascade, email text, display_name text, is_organizer boolean not null default false);
create table public.notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, meeting_id uuid references public.meetings(id) on delete set null, folder_id uuid references public.folders(id) on delete set null, title text not null default 'Untitled note', body text not null default '', is_draft boolean not null default true, elapsed_seconds integer not null default 0, tags jsonb not null default '[]', detected_links jsonb not null default '[]', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.note_blocks (id uuid primary key default gen_random_uuid(), note_id uuid not null references public.notes(id) on delete cascade, kind text not null check(kind in ('summary','decision','action_item','manual')), content jsonb not null, created_at timestamptz not null default now());
create table public.artifacts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, note_id uuid references public.notes(id) on delete cascade, meeting_id uuid references public.meetings(id) on delete set null, bucket text not null check(bucket in ('meeting-audio','meeting-artifacts')), storage_path text not null unique, mime_type text not null, byte_size bigint, duration_seconds integer, status text not null default 'pending' check(status in ('pending','uploaded','deleted','failed')), created_at timestamptz not null default now(), deleted_at timestamptz);
create table public.transcript_segments (id uuid primary key default gen_random_uuid(), note_id uuid not null references public.notes(id) on delete cascade, speaker_label text not null, start_ms integer not null, end_ms integer not null, text text not null);
create table public.speaker_mappings (id uuid primary key default gen_random_uuid(), note_id uuid not null references public.notes(id) on delete cascade, speaker_label text not null, attendee_id uuid not null references public.meeting_attendees(id) on delete cascade, unique(note_id,speaker_label));
create table public.processing_jobs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, note_id uuid not null references public.notes(id) on delete cascade, artifact_id uuid not null references public.artifacts(id) on delete cascade, type text not null default 'transcription', status text not null default 'queued' check(status in ('queued','processing','completed','failed')), attempts integer not null default 0, error text, created_at timestamptz not null default now(), completed_at timestamptz);
create table public.calendar_connections (user_id uuid primary key references auth.users(id) on delete cascade, encrypted_refresh_token text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.folders enable row level security; alter table public.meetings enable row level security; alter table public.meeting_attendees enable row level security; alter table public.notes enable row level security; alter table public.note_blocks enable row level security; alter table public.artifacts enable row level security; alter table public.transcript_segments enable row level security; alter table public.speaker_mappings enable row level security; alter table public.processing_jobs enable row level security; alter table public.calendar_connections enable row level security;
create policy "own profiles" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own folders" on public.folders for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own meetings" on public.meetings for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own notes" on public.notes for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own artifacts" on public.artifacts for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own jobs" on public.processing_jobs for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own calendar connection" on public.calendar_connections for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "meeting attendee access" on public.meeting_attendees for all using (exists(select 1 from public.meetings m where m.id=meeting_id and m.user_id=auth.uid()));
create policy "note block access" on public.note_blocks for all using (exists(select 1 from public.notes n where n.id=note_id and n.user_id=auth.uid()));
create policy "transcript access" on public.transcript_segments for all using (exists(select 1 from public.notes n where n.id=note_id and n.user_id=auth.uid()));
create policy "speaker map access" on public.speaker_mappings for all using (exists(select 1 from public.notes n where n.id=note_id and n.user_id=auth.uid()));
insert into storage.buckets(id,name,public) values ('meeting-audio','meeting-audio',false),('meeting-artifacts','meeting-artifacts',false) on conflict do nothing;
create policy "own media" on storage.objects for all using (bucket_id in ('meeting-audio','meeting-artifacts') and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id in ('meeting-audio','meeting-artifacts') and (storage.foldername(name))[1]=auth.uid()::text);
